package com.shopsphere.service; import com.shopsphere.entity.*; import com.shopsphere.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AdminService {private final UserRepository users;private final OrderRepository orders;private final ProductRepository products;public AdminService(UserRepository u,OrderRepository o,ProductRepository p){users=u;orders=o;products=p;} public Map<String,Object> dashboard(){return Map.of("users",users.count(),"orders",orders.count(),"products",products.count());} public void updateOrder(UUID id,OrderStatus status){Order o=orders.findById(id).orElseThrow();o.setStatus(status);}}
